package com.chari.chariapp.additionaldocument.infrastructure.persistence;
import com.chari.chariapp.additionaldocument.application.port.out.AdditionalDocumentAttachmentStore; import com.chari.chariapp.additionaldocument.domain.AdditionalDocumentAttachment; import java.util.*; import org.springframework.stereotype.Repository;
@Repository class JpaAdditionalDocumentAttachmentStore implements AdditionalDocumentAttachmentStore {private final SpringDataAdditionalDocumentAttachmentRepository repository;JpaAdditionalDocumentAttachmentStore(SpringDataAdditionalDocumentAttachmentRepository repository){this.repository=repository;}public AdditionalDocumentAttachment save(AdditionalDocumentAttachment a){return repository.save(AdditionalDocumentAttachmentJpaEntity.from(a)).toDomain();}public List<AdditionalDocumentAttachment> findByAdditionalRequestId(UUID id){return repository.findByAdditionalRequestIdOrderByUploadedAtAsc(id.toString()).stream().map(AdditionalDocumentAttachmentJpaEntity::toDomain).toList();}public Optional<AdditionalDocumentAttachment> findByIdAndAdditionalRequestId(UUID id,UUID requestId){return repository.findByIdAndAdditionalRequestId(id.toString(),requestId.toString()).map(AdditionalDocumentAttachmentJpaEntity::toDomain);}}
